-- Verification: expected total = 13,864 rows.
SELECT table_name, row_count FROM (
    SELECT 'territories' AS table_name, COUNT(*) AS row_count FROM raw."territories"
    UNION ALL
    SELECT 'states' AS table_name, COUNT(*) AS row_count FROM raw."states"
    UNION ALL
    SELECT 'users' AS table_name, COUNT(*) AS row_count FROM raw."users"
    UNION ALL
    SELECT 'products' AS table_name, COUNT(*) AS row_count FROM raw."products"
    UNION ALL
    SELECT 'accounts' AS table_name, COUNT(*) AS row_count FROM raw."accounts"
    UNION ALL
    SELECT 'contacts' AS table_name, COUNT(*) AS row_count FROM raw."contacts"
    UNION ALL
    SELECT 'leads' AS table_name, COUNT(*) AS row_count FROM raw."leads"
    UNION ALL
    SELECT 'opportunities' AS table_name, COUNT(*) AS row_count FROM raw."opportunities"
    UNION ALL
    SELECT 'opportunity_stage_history' AS table_name, COUNT(*) AS row_count FROM raw."opportunity_stage_history"
    UNION ALL
    SELECT 'activities' AS table_name, COUNT(*) AS row_count FROM raw."activities"
    UNION ALL
    SELECT 'opportunity_products' AS table_name, COUNT(*) AS row_count FROM raw."opportunity_products"
    UNION ALL
    SELECT 'deal_approvals' AS table_name, COUNT(*) AS row_count FROM raw."deal_approvals"
    UNION ALL
    SELECT 'opportunity_close_date_history' AS table_name, COUNT(*) AS row_count FROM raw."opportunity_close_date_history"
    UNION ALL
    SELECT 'opportunity_forecast_snapshots' AS table_name, COUNT(*) AS row_count FROM raw."opportunity_forecast_snapshots"
) x
ORDER BY table_name;

SELECT SUM(row_count) AS total_rows FROM (
    SELECT 'territories' AS table_name, COUNT(*) AS row_count FROM raw."territories"
